// decodeUnprofiledLayerProfile probes only the generated invariant
// invokeWithLayer prefix. The original buffer is not consumed; exact
// admission re-decodes the complete request with the selected profile.
func decodeUnprofiledLayerProfile(b *bin.Buffer) (LayerProfile, error) {
	if b == nil {
		return LayerProfile(0), &LayerCodecError{Operation: "probe unprofiled RPC wrapper", Reason: "nil buffer"}
	}
	probe := *b
	id, err := probe.PeekID()
	if err != nil {
		return LayerProfile(0), err
	}
	if id != 0xda9b0d0d {
		return LayerProfile(0), &LayerCodecError{Operation: "probe unprofiled RPC wrapper", WireID: id, Reason: "only invariant invokeWithLayer is accepted before profile freeze"}
	}
	if err := probe.ConsumeID(0xda9b0d0d); err != nil {
		return LayerProfile(0), fmt.Errorf("consume unprofiled invokeWithLayer probe: %w", err)
	}
	selectedLayer, err := probe.Int()
	if err != nil {
		return LayerProfile(0), fmt.Errorf("decode unprofiled invokeWithLayer layer probe: %w", err)
	}
	selectedProfile, ok := ResolveLayerProfile(selectedLayer)
	if !ok {
		return LayerProfile(0), &LayerCodecError{Operation: "probe unprofiled RPC wrapper", Semantic: LayerSemanticMethodInvokeWithLayer, WireID: 0xda9b0d0d, Reason: fmt.Sprintf("invokeWithLayer selected unsupported exact profile %d", selectedLayer)}
	}
	return selectedProfile, nil

}

